'use client';

import { FlaskConical } from 'lucide-react';

import type { DataSource } from '../../types';

interface SimulatedDataBannerProps {
  isSimulated: boolean;
  dataSource?: DataSource;
}

/**
 * Shown whenever any displayed frame was generated by the backend's offline
 * demo fallback instead of being downloaded from the SPHEREx archive (IRSA).
 * Simulated frames must never be mistaken for real observations.
 */
export default function SimulatedDataBanner({ isSimulated, dataSource }: SimulatedDataBannerProps) {
  if (!isSimulated) return null;

  const mixed = dataSource === 'mixed';
  return (
    <div
      role="alert"
      data-testid="simulated-data-banner"
      className="flex items-start gap-2 rounded border border-amber-400/60 bg-amber-400/10 p-3 text-xs text-amber-100"
    >
      <FlaskConical className="mt-0.5 h-4 w-4 shrink-0 text-amber-300" />
      <div className="space-y-1">
        <div className="font-mono font-bold uppercase tracking-wide text-amber-300">
          {mixed ? 'Partly simulated demo data' : 'Simulated demo data — not real SPHEREx images'}
        </div>
        <p className="text-amber-100/90">
          {mixed
            ? 'The SPHEREx archive could not deliver every frame in time, so some frames below are generated demo images. They carry a SIMULATED badge. Do not use them for science.'
            : 'The SPHEREx archive (IRSA) could not be reached or returned too little data, so these frames are generated for demonstration only. Any motion or brightness change you see is scripted, not observed. Try again in a moment for real data.'}
        </p>
      </div>
    </div>
  );
}
